// Renders the rule registry as Markdown: the current source for every rule, regenerated by
// `bun run definitions` and kept in sync by a test.
import { AREAS, type Area, type Rule } from "./registry";

const AREA_TITLES: Readonly<Record<Area, string>> = {
  recording: "Recording",
  match: "Match",
  identity: "Identity",
  attribution: "Attribution",
  extras: "Extras",
  goals: "Goals",
  queries: "Queries",
};

const HEADER = `# Stat rule definitions

<!-- Generated from src/server/rules/registry.ts by \`bun run definitions\`. Don't edit by hand. -->

Every rule we apply to the game's data, as it stands now. This file is the current source; plans,
ADRs and review logs are dated history that say why a rule was decided.

## Changing a rule
1. Edit its entry in \`src/server/rules/registry.ts\` and bump its \`version\`. Change one rule per
   run of step 2: a bump hides another rule's unbumped change from the WARNING. A changed constant
   without a bump fails \`bun run check\` and \`bun run definitions\`.
2. Run \`bun run rules-diff\` and read every moved column, not only the WARNING. A match that
   changed while no rule's version did is a WARNING: bump the rule that changed, or add a
   recorded rule for what moved if none covers it. A moved column none of whose listed rules was
   bumped, or that no rule lists, is a "review:" line: the lists are best-effort, so look at
   whether the bumped rule explains it.
3. Write an ADR if the change passes the ADR gate.
4. Run \`bun run definitions\` to regenerate this file and the constant pins.
5. Run \`bun run deploy\`.

**When applied**:
- *stored*: while recording, into raw.db; recompute can't change it.
- *recorded*: when a match's record is computed, live or by recompute; each record stores these
  rules' versions.
- *read*: when a page reads the record, so it always applies at its current version.

A *dense* rule reads every UpdateState. Once retention has thinned a match, the match keeps the
outputs snapshotted when it was thinned, and the rule's version from then, so a change to a dense
rule reaches only matches still whole (recent or flagged ones).
`;

const code = (items: readonly string[]) => items.map((i) => `\`${i}\``).join(", ");

function renderRule(r: Rule): string {
  const lines = [`### \`${r.id}\` · v${String(r.version)} · ${r.applied}${r.dense ? " · dense" : ""}`, "", r.rule, ""];
  const constants = Object.entries(r.constants ?? {});
  if (constants.length) lines.push(`- **Constants**: ${constants.map(([k, v]) => `\`${k}\` = ${String(v)}`).join(", ")}`);
  if (r.checks.length) lines.push(`- **Checks**: ${code(r.checks)}`);
  if (r.outputs?.length) lines.push(`- **Writes**: ${code(r.outputs)}`);
  lines.push(`- **Evidence**: ${r.evidence}`, `- **Decided in**: ${code(r.refs)}`);
  return lines.join("\n");
}

export function renderDefinitions(rules: readonly Rule[]): string {
  const sections = AREAS.flatMap((area) => {
    const inArea = rules.filter((r) => r.area === area);
    return inArea.length ? [`## ${AREA_TITLES[area]}\n\n${inArea.map(renderRule).join("\n\n")}`] : [];
  });
  return `${[HEADER, ...sections].join("\n")}\n`;
}

/** Each rule's constants at its version, by rule id. */
export type Pins = Record<string, { version: number; constants: Readonly<Record<string, number>> }>;

/** The pins for the rules that have constants. */
export function pinsOf(rules: readonly Rule[]): Pins {
  return Object.fromEntries(rules.filter((r) => r.constants).map((r) => [r.id, { version: r.version, constants: r.constants ?? {} }]));
}

// A newly listed constant has no pinned value to compare; one no longer listed counts as changed,
// or a rename or an unlisting could carry a new value past the pin.
const pinBroken = (pinned: Readonly<Record<string, number>>, now: Readonly<Record<string, number>>) =>
  Object.entries(pinned).some(([k, v]) => now[k] !== v);

/** Rules whose pinned constants changed value or went unlisted at the pinned version: each needs a bump. */
export function unbumpedConstants(rules: readonly Rule[], pins: Pins): string[] {
  return rules
    .filter((r) => {
      const pin = pins[r.id];
      return pin?.version === r.version && pinBroken(pin.constants, r.constants ?? {});
    })
    .map((r) => r.id);
}
